import { type VNodeChild, RenderListCache } from '../vnode'
import {
  ArrayIterateView,
  ReactiveSourceProfile,
  shallowReadArray,
  toReactive,
} from '@vue/reactivity'
import { isObject } from '@vue/shared'
import { warn } from '../warning'

class ListRenderer {
  wrapReactiveItems: boolean
  allowRangeWarning: boolean

  constructor() {
    this.wrapReactiveItems = true
    this.allowRangeWarning = true
  }

  renderSource(
    profile: ReactiveSourceProfile,
    view: ArrayIterateView,
    cacheView: RenderListCache,
    renderItem: (...args: any[]) => VNodeChild,
  ): VNodeChild[] {
    let ret: VNodeChild[]
    let source = profile.value
    const cached = cacheView.nodes
    const sourceIsArray = view.isArray

    if (sourceIsArray || view.isString) {
      const isReactiveSource = sourceIsArray && profile.isReactive
      if (isReactiveSource) {
        source = shallowReadArray(source)
      }
      ret = new Array(source.length)
      for (let i = 0, l = source.length; i < l; i++) {
        ret[i] = renderItem(
          isReactiveSource && this.wrapReactiveItems
            ? toReactive(source[i])
            : source[i],
          i,
          undefined,
          cached && cached[i],
        )
      }
    } else if (view.isNumber) {
      if (__DEV__ && this.allowRangeWarning && !Number.isInteger(source)) {
        warn(`The v-for range expect an integer value but got ${source}.`)
      }
      ret = new Array(source)
      for (let i = 0; i < source; i++) {
        ret[i] = renderItem(i + 1, i, undefined, cached && cached[i])
      }
    } else if (isObject(source)) {
      if (view.isIterable) {
        ret = Array.from(view.source as Iterable<any>, (item, i) =>
          renderItem(item, i, undefined, cached && cached[i]),
        )
      } else {
        const keys = Object.keys(source)
        ret = new Array(keys.length)
        for (let i = 0, l = keys.length; i < l; i++) {
          const key = keys[i]
          ret[i] = renderItem(source[key], key, i, cached && cached[i])
        }
      }
    } else {
      ret = []
    }

    cacheView.store(ret)
    return ret
  }
}

const listRenderer = new ListRenderer()

/**
 * v-for string
 * @private
 */
export function renderList(
  source: string,
  renderItem: (value: string, index: number) => VNodeChild,
): VNodeChild[]

/**
 * v-for number
 */
export function renderList(
  source: number,
  renderItem: (value: number, index: number) => VNodeChild,
): VNodeChild[]

/**
 * v-for array
 */
export function renderList<T>(
  source: T[],
  renderItem: (value: T, index: number) => VNodeChild,
): VNodeChild[]

/**
 * v-for iterable
 */
export function renderList<T>(
  source: Iterable<T>,
  renderItem: (value: T, index: number) => VNodeChild,
): VNodeChild[]

/**
 * v-for object
 */
export function renderList<T>(
  source: T,
  renderItem: <K extends keyof T>(
    value: T[K],
    key: string,
    index: number,
  ) => VNodeChild,
): VNodeChild[]

/**
 * Actual implementation
 */
export function renderList(
  source: any,
  renderItem: (...args: any[]) => VNodeChild,
  cache?: any[],
  index?: number,
): VNodeChild[] {
  return listRenderer.renderSource(
    new ReactiveSourceProfile(source),
    new ArrayIterateView(source),
    new RenderListCache(cache, index),
    renderItem,
  )
}

