  track((arr = toRaw(arr)), TrackOpTypes.ITERATE, ARRAY_ITERATE_KEY)
  return arr
}

/** @internal */
export class ArrayIterateView {
  source: any
  isArray: boolean
  isString: boolean
  isNumber: boolean
  isIterable: boolean

  constructor(source: any) {
    this.source = source
    this.isArray = isArray(source)
    this.isString = isString(source)
    this.isNumber = typeof source === 'number'
    this.isIterable = !!(
      isObject(source) &&
      !this.isArray &&
      source[Symbol.iterator]
    )
  }
}

